-- S10D AUTHORING ONLY. This fixture has not been executed.
-- Exact NEW S10D disposable server/database/case authorization and backup/actual restore
-- evidence are required separately. Never target or reuse retained S6/S8/S10A databases.
-- Caller supplies #S10DMigrationInput: exactly one reviewed row with SqlText nvarchar(max),
-- ExpectedUtf16Hash binary(32), BackupEvidence nvarchar(1024), RestoreEvidence nvarchar(1024).
-- Pin UTF-8 file hash separately. No SQLCMD, network input, bootstrap or predecessor rerun.
-- SESSION_CONTEXT: S10D_AUTHORIZED=1, S10D_SERVER, S10D_DATABASE, S10D_CASE.
-- Modes: install, constraints, partial, type_conflict, inherited_drift, drift, preservation.
-- All case schema/data rolls back. Preservation accepts separately seeded S10D-only history;
-- other modes require empty prerequisite/export/output application tables.
-- Real two-connection races, lost acknowledgements and provider operations remain separate.
SET NOCOUNT ON;
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
IF @@TRANCOUNT<>0 THROW 51910,'S10D fixture refuses an ambient transaction.',1;
IF COALESCE(TRY_CONVERT(int,SESSION_CONTEXT(N'S10D_AUTHORIZED')),0)<>1
 OR SESSION_CONTEXT(N'S10D_SERVER') IS NULL OR SESSION_CONTEXT(N'S10D_DATABASE') IS NULL
 OR CONVERT(nvarchar(128),SESSION_CONTEXT(N'S10D_SERVER')) COLLATE Latin1_General_100_BIN2<>CONVERT(nvarchar(128),SERVERPROPERTY('ServerName')) COLLATE Latin1_General_100_BIN2
 OR CONVERT(nvarchar(128),SESSION_CONTEXT(N'S10D_DATABASE')) COLLATE Latin1_General_100_BIN2<>DB_NAME() COLLATE Latin1_General_100_BIN2
 OR DATALENGTH(CONVERT(nvarchar(128),SESSION_CONTEXT(N'S10D_SERVER')))<>DATALENGTH(CONVERT(nvarchar(128),SERVERPROPERTY('ServerName')))
 OR DATALENGTH(CONVERT(nvarchar(128),SESSION_CONTEXT(N'S10D_DATABASE')))<>DATALENGTH(DB_NAME())
 OR DB_ID()<=4 OR DB_NAME() NOT LIKE N'K98[_]S10D[_]Disposable[_]%'
 THROW 51910,'Exact new S10D disposable target authorization required.',1;
DECLARE @Case varchar(32)=CONVERT(varchar(32),SESSION_CONTEXT(N'S10D_CASE'));
IF @Case IS NULL OR @Case COLLATE Latin1_General_100_BIN2 NOT IN ('install','constraints','partial','type_conflict','inherited_drift','drift','preservation') OR DATALENGTH(@Case)<>LEN(@Case)
 THROW 51910,'Exact S10D case required.',1;
IF OBJECT_ID(N'tempdb..#S10DMigrationInput') IS NULL THROW 51910,'Reviewed S10D migration and safety evidence required.',1;
DECLARE @Migration nvarchar(max);
EXEC sys.sp_executesql N'IF (SELECT COUNT_BIG(*) FROM #S10DMigrationInput)<>1 OR EXISTS
 (SELECT 1 FROM #S10DMigrationInput WHERE SqlText IS NULL OR ExpectedUtf16Hash IS NULL
 OR HASHBYTES(''SHA2_256'',CONVERT(varbinary(max),SqlText))<>ExpectedUtf16Hash
 OR BackupEvidence IS NULL OR LEN(BackupEvidence)=0 OR RestoreEvidence IS NULL OR LEN(RestoreEvidence)=0)
 THROW 51910,''Reviewed S10D bytes or backup/actual-restore evidence invalid.'',1;
 SELECT @Text=SqlText FROM #S10DMigrationInput;',N'@Text nvarchar(max) OUTPUT',@Text=@Migration OUTPUT;
DECLARE @ExpectedObjects int=CASE WHEN @Case IN ('constraints','drift','preservation') THEN 4 ELSE 0 END;
IF EXISTS(SELECT 1 FROM sys.objects WHERE schema_id=SCHEMA_ID(N'KVK') AND name IN ('SourceOutputFile','SourceOutputPool','SourceOutputSlot','SourceOutputDisposition') AND type<>'U')
 OR (SELECT COUNT(*) FROM sys.tables WHERE schema_id=SCHEMA_ID(N'KVK') AND name IN ('SourceOutputFile','SourceOutputPool','SourceOutputSlot','SourceOutputDisposition'))<>@ExpectedObjects
 THROW 51910,'Fixture requires exact initial S10D object state; preserve existing state.',1;
IF @Case<>'preservation'
BEGIN
 EXEC sys.sp_executesql N'IF EXISTS(SELECT 1 FROM KVK.SeasonSource) OR EXISTS(SELECT 1 FROM KVK.SourceExportIntent)
 OR EXISTS(SELECT 1 FROM KVK.SourceDelivery) OR EXISTS(SELECT 1 FROM KVK.SourcePublication)
 OR EXISTS(SELECT 1 FROM dbo.ExportJob) OR EXISTS(SELECT 1 FROM dbo.ExportAttempt) OR EXISTS(SELECT 1 FROM dbo.ExportAttemptPart)
 OR EXISTS(SELECT 1 FROM dbo.ExportResource) OR EXISTS(SELECT 1 FROM dbo.ExportJobResource)
 OR EXISTS(SELECT 1 FROM dbo.ExportPreparation) OR EXISTS(SELECT 1 FROM dbo.ExportPreparationResource) OR EXISTS(SELECT 1 FROM dbo.ExportRequestBudget)
 THROW 51910,''Fixture requires empty prerequisite/export tables; no retained history targets.'',1;';
 IF @ExpectedObjects=4 EXEC sys.sp_executesql N'IF EXISTS(SELECT 1 FROM KVK.SourceOutputFile) OR EXISTS(SELECT 1 FROM KVK.SourceOutputPool) OR EXISTS(SELECT 1 FROM KVK.SourceOutputSlot) OR EXISTS(SELECT 1 FROM KVK.SourceOutputDisposition)
 THROW 51910,''Fixture requires empty S10D tables.'',1;';
END;
DECLARE @WasXactAbort bit=CASE WHEN (16384 & @@OPTIONS)=16384 THEN 1 ELSE 0 END;
BEGIN TRANSACTION;
BEGIN TRY
 DECLARE @Rejected bit=0;
 IF @Case IN ('partial','type_conflict','inherited_drift','drift')
 BEGIN
  IF @Case='partial' EXEC sys.sp_executesql N'CREATE TABLE KVK.SourceOutputFile (SyntheticValue int NOT NULL);';
  IF @Case='type_conflict' EXEC sys.sp_executesql N'CREATE VIEW KVK.SourceOutputFile AS SELECT CONVERT(int,1) AS SyntheticValue;';
  IF @Case='inherited_drift' EXEC sys.sp_executesql N'ALTER TABLE dbo.ExportResource NOCHECK CONSTRAINT CK_ExportResource_Ownership;';
  IF @Case='drift' EXEC sys.sp_executesql N'ALTER TABLE KVK.SourceOutputSlot NOCHECK CONSTRAINT FK_SourceOutputSlot_File;';
  BEGIN TRY
   EXEC sys.sp_executesql @Migration;
  END TRY
  BEGIN CATCH
   IF ERROR_NUMBER()<>51500 THROW;
   IF @Case='partial' AND ERROR_MESSAGE() NOT LIKE 'Partial S10D schema;%' THROW;
   IF @Case='type_conflict' AND ERROR_MESSAGE() NOT LIKE 'S10D object type conflict;%' THROW;
   IF @Case='inherited_drift' AND ERROR_MESSAGE() NOT LIKE 'S10D check constraint shape conflict;%' THROW;
   IF @Case='drift' AND ERROR_MESSAGE() NOT LIKE 'S10D foreign key shape conflict;%' THROW;
   SET @Rejected=1;
  END CATCH;
  IF @Rejected=0 THROW 51911,'Drifted/partial S10D was accepted.',1;
 END
 ELSE IF @Case='preservation'
 BEGIN
 EXEC sys.sp_executesql N'-- Nonempty sentinels are mandatory: an empty comparison is not receipt proof.
IF NOT EXISTS(SELECT 1 FROM KVK.SourceDelivery WHERE Receipt IS NOT NULL)
 OR NOT EXISTS(SELECT 1 FROM dbo.ExportAttempt WHERE ReceiptJson IS NOT NULL AND Phase=''uncertain'')
 OR NOT EXISTS(SELECT 1 FROM dbo.ExportResource WHERE OwnerID IS NOT NULL OR BlockedReason IS NOT NULL)
 THROW 51910,''Preservation requires separately seeded S10D receipt/uncertain-claim sentinels.'',1;
SELECT PublicationID,DestinationKind,DestinationID,CONVERT(varbinary(max),Receipt) AS Bytes,DATALENGTH(Receipt) AS ByteCount,OwnerID,Fence,DeliveryState INTO #S10DReceiptBefore FROM KVK.SourceDelivery;
SELECT AttemptID,CONVERT(varbinary(max),ReceiptJson) AS Bytes,DATALENGTH(ReceiptJson) AS ByteCount,CONVERT(varbinary(max),ManifestJson) AS ManifestBytes,OwnerID,Fence,Epoch,Version,Phase INTO #S10DAttemptBefore FROM dbo.ExportAttempt;
SELECT ResourceKey,ActiveJobID,ActivePreparationID,OwnerID,Fence,Version,CONVERT(varbinary(max),BlockedReason) AS BlockedBytes INTO #S10DResourceBefore FROM dbo.ExportResource;
EXEC sys.sp_executesql @ReviewedMigration;
IF EXISTS(SELECT * FROM #S10DReceiptBefore EXCEPT SELECT PublicationID,DestinationKind,DestinationID,CONVERT(varbinary(max),Receipt),DATALENGTH(Receipt),OwnerID,Fence,DeliveryState FROM KVK.SourceDelivery)
 OR EXISTS(SELECT PublicationID,DestinationKind,DestinationID,CONVERT(varbinary(max),Receipt),DATALENGTH(Receipt),OwnerID,Fence,DeliveryState FROM KVK.SourceDelivery EXCEPT SELECT * FROM #S10DReceiptBefore)
 OR EXISTS(SELECT * FROM #S10DAttemptBefore EXCEPT SELECT AttemptID,CONVERT(varbinary(max),ReceiptJson),DATALENGTH(ReceiptJson),CONVERT(varbinary(max),ManifestJson),OwnerID,Fence,Epoch,Version,Phase FROM dbo.ExportAttempt)
 OR EXISTS(SELECT AttemptID,CONVERT(varbinary(max),ReceiptJson),DATALENGTH(ReceiptJson),CONVERT(varbinary(max),ManifestJson),OwnerID,Fence,Epoch,Version,Phase FROM dbo.ExportAttempt EXCEPT SELECT * FROM #S10DAttemptBefore)
 OR EXISTS(SELECT * FROM #S10DResourceBefore EXCEPT SELECT ResourceKey,ActiveJobID,ActivePreparationID,OwnerID,Fence,Version,CONVERT(varbinary(max),BlockedReason) FROM dbo.ExportResource)
 OR EXISTS(SELECT ResourceKey,ActiveJobID,ActivePreparationID,OwnerID,Fence,Version,CONVERT(varbinary(max),BlockedReason) FROM dbo.ExportResource EXCEPT SELECT * FROM #S10DResourceBefore)
 THROW 51911,''Rerun changed receipt bytes or retained claims.'',1;
',N'@ReviewedMigration nvarchar(max)',@ReviewedMigration=@Migration;
 END
 ELSE
 BEGIN
 EXEC sys.sp_executesql @Migration;
 EXEC sys.sp_executesql @Migration; -- compatible rerun; never a predecessor migration
 SET XACT_ABORT OFF;
 -- S10D_CASE_BODY_BEGIN
 EXEC sys.sp_executesql N'INSERT KVK.SeasonSource VALUES (2147483300,''snapshot_report_v1'',''56e4b886-0c04-5782-a696-e905d451ba8b'',N''synthetic'',CONVERT(datetime2(0),''2026-09-15T00:00:00''),N''S10D fixture'',N''{}'',''open'',1);
