DECLARE @N int=1,@Sql nvarchar(max),@Name varchar(100),@Expected int,@Caught int;
WHILE @N<=(SELECT COUNT(*) FROM @Cases)
BEGIN
 SELECT @Sql=SqlText,@Name=Name,@Expected=ExpectedError FROM @Cases WHERE CaseNo=@N;
 SET @Caught=0;
 SAVE TRANSACTION S10DCase;
 BEGIN TRY
  EXEC sys.sp_executesql @Sql;
 END TRY
 BEGIN CATCH
  SET @Caught=ERROR_NUMBER();
  IF XACT_STATE()<>1 THROW;
  IF @Expected=0 OR (@Caught<>@Expected AND NOT (@Expected=2601 AND @Caught=2627)) THROW;
 END CATCH;
 ROLLBACK TRANSACTION S10DCase;
 IF (@Expected=0 AND @Caught<>0) OR (@Expected<>0 AND @Caught=0)
  THROW 51911,''S10D structural case had unexpected outcome.'',1;
 SELECT @Name AS CaseName,''PASS'' AS Outcome;
 SET @N+=1;
END;
';
 -- S10D_CASE_BODY_END
 END;
 ROLLBACK TRANSACTION;
END TRY
BEGIN CATCH
 IF XACT_STATE()<>0 ROLLBACK TRANSACTION;
 IF @WasXactAbort=1 SET XACT_ABORT ON ELSE SET XACT_ABORT OFF;
 THROW;
END CATCH;
IF @WasXactAbort=1 SET XACT_ABORT ON ELSE SET XACT_ABORT OFF;
SELECT @Case AS FixtureMode,'PASS; all fixture changes rolled back' AS Outcome;
